MOD = 1000000007

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    edges = []
    idx = 1
    for i in range(1, n):
        u = int(data[idx])
        v = int(data[idx + 1])
        edges.append((u, v))
        idx += 2

    decorations = list(map(int, data[-n:]))

    # Construct the tree
    tree = [[] for _ in range(n + 1)]
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    def dfs(node, parent):
        if decorations[node - 1] != 0:
            dp[node] = [0] * (n + 1)
            dp[node][decorations[node - 1]] = 1
        else:
            for i in range(1, n + 1):
                dp[node][i] = 1

        for child in tree[node]:
            if child == parent:
                continue
            dfs(child, node)
            new_dp = [[0] * (n + 1) for _ in range(n + 1)]
            for i in range(1, n + 1):
                for j in range(1, n + 1):
                    for k in range(1, n + 1):
                        for l in range(1, n + 1):
                            if k == l:
                                new_dp[i][k] = (new_dp[i][k] + dp[node][i] * dp[child][j]) % MOD
            dp[node] = new_dp

    dfs(1, -1)

    result = 0
    for i in range(1, n + 1):
        result = (result + sum(dp[1][i]) % MOD) % MOD

    print(result)

if __name__ == "__main__":
    main()
